import type { Currency } from "@/types/currency.types"

/** The currencies the API can price a product in. The public catalog serves PKR. */
export type StorefrontCurrency = Currency

export type StorefrontProductImage = {
  url: string
  /** What the picture shows, generated by the API from the product's name. */
  alt: string
}

/** A product as the public catalog API returns it. Prices and stock are the server's. */
export type StorefrontProduct = {
  /** Public id, "PRD-1001". */
  id: string
  name: string
  subtitle: string | null
  description: string | null
  brand: string | null
  category: { id: string; name: string }
  /** In `currency`. */
  price: number
  currency: StorefrontCurrency
  /** The primary image; null when the product has none. */
  image: StorefrontProductImage | null
  /** Further images, in display order, after `image`. */
  gallery: StorefrontProductImage[]
  /** False for a sold-out product, which the catalog still lists. */
  inStock: boolean
}

export type StorefrontSort = "newest" | "price_asc" | "price_desc" | "name"

/** Everything that decides which page of the catalog the server returns. */
export type StorefrontProductsQuery = {
  search: string
  page: number
  pageSize: number
  sort: StorefrontSort
  categoryId?: string
}

export type StorefrontPageMeta = {
  page: number
  pageSize: number
  total: number
  totalPages: number
}

export type StorefrontProductPage = {
  products: StorefrontProduct[]
  meta: StorefrontPageMeta
}
